<script setup>import {ref,onBeforeUnmount} from 'vue';import {useRoute} from 'vue-router';import {getCharacter,demoMode} from '../services/api';import {useLibrary} from '../stores/library';import SourceList from '../components/SourceList.vue';const lib=useLibrary(),route=useRoute(),input=ref(String(route.query.char||'日')),item=ref(null),loading=ref(false),error=ref('');let controller;async function search(c=input.value){controller?.abort();const active=controller=new AbortController();input.value=c;item.value=null;error.value='';if(Array.from(c.trim()).length!==1){error.value='请输入一个汉字。';loading.value=false;return}loading.value=true;try{const result=await getCharacter(c.trim(),active.signal);if(controller!==active)return;item.value=result;lib.visit(result.character)}catch(e){if(controller===active&&e.name!=='AbortError')error.value=e.message}finally{if(controller===active)loading.value=false}}onBeforeUnmount(()=>controller?.abort());search();</script><template><section class="section"><span class="sub">CHAPTER 02 / 寻字溯源</span><h2>你的名字，藏着什么故事？</h2><p class="quiet">{{demoMode?'演示字库：日、山、水、木。':'连接团队后端字库。'}}</p><form class="lookup-form" @submit.prevent="search()"><input v-model="input" aria-label="输入一个汉字" placeholder="输入一个汉字"><button class="primary">查询 →</button></form><div class="toolbar"><button v-for="c in ['日','山','水','木']" :key="c" @click="search(c)">{{c}}</button></div><p v-if="loading" role="status">正在寻找这个字的故事…</p><p v-if="error" role="alert" class="error">{{error}}</p><article v-if="item" class="study"><div class="sample">{{item.character}}</div><h2>一字一故事 · {{item.character}}</h2><p>{{item.description}}</p><SourceList :sources="item.sources"/><div class="toolbar"><button @click="lib.toggle(item.character)">{{lib.saved.includes(item.character)?'取消收藏':'收藏此字'}}</button><RouterLink class="primary" :to="{path:'/study',query:{char:item.character}}">放入临写格</RouterLink></div></article></section></template>
